import React from 'react';
import PropTypes from 'prop-types';
// import './ViewBookings.css'; // Include styling if necessary

const ViewBookings = ({ bookings }) => {
  if (!bookings || bookings.length === 0) {
    return <p>No bookings available.</p>;
  }

  return (
    <div className="view-bookings">
      <h3>Event Bookings</h3>
      <ul>
        {bookings.map((booking) => (
          <li key={booking.id} className="booking-item">
            <h4>{booking.eventName}</h4>
            <p>Booking ID: {booking.id}</p>
            <p>User: {booking.userName}</p>
            <p>Seats: {booking.seats}</p>
            <p>Date: {booking.bookingDate}</p>
          </li>
        ))}
      </ul>
    </div>
  );
};

// Define the prop types for validation
ViewBookings.propTypes = {
  bookings: PropTypes.arrayOf(
    PropTypes.shape({
      id: PropTypes.number.isRequired,
      eventName: PropTypes.string.isRequired,
      userName: PropTypes.string.isRequired,
      seats: PropTypes.number.isRequired,
      bookingDate: PropTypes.string.isRequired,
    })
  ).isRequired,
};

export default ViewBookings;


